static int hexval(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    return (c | 0x20) - 'a' + 10;
}

static void run_child(const char* self, const char* mode) {
    char cmd[MAX_PATH * 2];
    STARTUPINFOA si;
    PROCESS_INFORMATION pi;
    DWORD code = 0xFFFFFFFF;
    snprintf(cmd, sizeof(cmd), "\"%s\" %s", self, mode);
    memset(&si, 0, sizeof(si));
    si.cb = sizeof(si);
    if (CreateProcessA(NULL, cmd, NULL, NULL, FALSE, 0, NULL, NULL, &si, &pi)) {
        WaitForSingleObject(pi.hProcess, INFINITE);
        GetExitCodeProcess(pi.hProcess, &code);
        CloseHandle(pi.hThread);
        CloseHandle(pi.hProcess);
    }
    printf("child_%s\texit\t%08lx\n", mode, (unsigned long)code);
}

int main(int argc, char** argv) {
    size_t i;
    if (argc > 1) {
        // Child: the result is the exit code (BOOL, or the fault code).
        CRYPT_DATA_BLOB b;
        SetErrorMode(SEM_NOGPFAULTERRORBOX | SEM_FAILCRITICALERRORS);
        if (strcmp(argv[1], "null_blob") == 0) return PFXIsPFXBlob(NULL) ? 1 : 0;
        b.cbData = 16;
        b.pbData = NULL;
        if (strcmp(argv[1], "null_pb_cb16") == 0) return PFXIsPFXBlob(&b) ? 1 : 0;
        {
            // A released page: pbData that is non-NULL but unreadable.
            BYTE* page = (BYTE*)VirtualAlloc(NULL, 4096, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
            VirtualFree(page, 0, MEM_RELEASE);
            b.pbData = page;
            if (strcmp(argv[1], "freed_pb_cb16") == 0) return PFXIsPFXBlob(&b) ? 1 : 0;
            if (strcmp(argv[1], "freed_blob") == 0)
                return PFXIsPFXBlob((CRYPT_DATA_BLOB*)page) ? 1 : 0;
        }
        {
            // A real PFX whose cbData runs past the end of its readable page.
            BYTE* two = (BYTE*)VirtualAlloc(NULL, 8192, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
            DWORD old;
            const char* hex = cases[3][1];  // real_pfx
            size_t n = strlen(hex) / 2, j;
            BYTE* start = two + 4096 - n;
            for (j = 0; j < n; ++j)
                start[j] = (BYTE)(hexval(hex[2 * j]) << 4 | hexval(hex[2 * j + 1]));
            VirtualProtect(two + 4096, 4096, PAGE_NOACCESS, &old);
            b.pbData = start;
            b.cbData = (DWORD)n + 64;
            if (strcmp(argv[1], "pfx_cb_past_page") == 0) return PFXIsPFXBlob(&b) ? 1 : 0;
            b.cbData = (DWORD)n;
            if (strcmp(argv[1], "pfx_at_page_end") == 0) return PFXIsPFXBlob(&b) ? 1 : 0;
        }
        return 0x77;
    }
    {
        CRYPT_DATA_BLOB b = {0, NULL};
        BOOL r;
        SetLastError(0xDEADBEEF);
        r = PFXIsPFXBlob(&b);
        printf("null_pb_cb0\t%d\t%08lx\n", r, (unsigned long)GetLastError());
    }
    for (i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        const char* hex = cases[i][1];
        size_t n = strlen(hex) / 2, j;
        BYTE* buf = (BYTE*)malloc(n ? n : 1);
        CRYPT_DATA_BLOB b;
        BOOL r;
        for (j = 0; j < n; ++j)
            buf[j] = (BYTE)(hexval(hex[2 * j]) << 4 | hexval(hex[2 * j + 1]));
        b.cbData = (DWORD)n;
        b.pbData = buf;
        SetLastError(0xDEADBEEF);
        r = PFXIsPFXBlob(&b);
        printf("%s\t%d\t%08lx\n", cases[i][0], r, (unsigned long)GetLastError());
        free(buf);
    }
    run_child(argv[0], "null_blob");
    run_child(argv[0], "null_pb_cb16");
    run_child(argv[0], "freed_pb_cb16");
    run_child(argv[0], "freed_blob");
    run_child(argv[0], "pfx_cb_past_page");
    run_child(argv[0], "pfx_at_page_end");
    return 0;
}
